<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Computer Languages Quiz</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f5f7fb;
        --surface: #ffffff;
        --surface-alt: #f8fafc;
        --text: #132238;
        --muted: #5b6b84;
        --border: #d7e0eb;
        --border-strong: #9db0c7;
        --accent: #3b82f6;
        --accent-strong: #2563eb;
        --accent-soft: #eaf2ff;
        --shadow: 0 20px 50px rgba(16, 24, 40, 0.12);
        --radius: 20px;
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, #ffffff 0%, var(--bg) 45%, #edf2f7 100%);
        min-height: 100vh;
      }

      a.skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        padding: 0.75rem 1rem;
        background: var(--surface);
        color: var(--text);
        border: 2px solid var(--accent);
        border-radius: 999px;
        transform: translateY(-200%);
        transition: transform 0.2s ease;
        z-index: 1000;
      }

      a.skip-link:focus {
        transform: translateY(0);
      }

      main {
        width: min(960px, calc(100% - 2rem));
        margin: 0 auto;
        padding: 4.5rem 0 3rem;
      }

      .hero {
        margin-bottom: 1.5rem;
        display: grid;
        gap: 0.75rem;
      }

      .eyebrow {
        display: inline-flex;
        width: fit-content;
        align-items: center;
        gap: 0.5rem;
        padding: 0.35rem 0.75rem;
        border-radius: 999px;
        background: var(--accent-soft);
        color: var(--accent-strong);
        font-size: 0.875rem;
        font-weight: 600;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 4vw, 3.5rem);
        line-height: 1.05;
        letter-spacing: -0.04em;
      }

      .lead {
        max-width: 62ch;
        margin: 0;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.6;
      }

      .card {
        margin-top: 2rem;
        padding: clamp(1rem, 2vw, 1.5rem);
        border: 1px solid var(--border);
        border-radius: var(--radius);
        background: rgba(255, 255, 255, 0.8);
        box-shadow: var(--shadow);
        backdrop-filter: blur(10px);
      }

      form {
        display: grid;
        gap: 1rem;
      }

      .form-field {
        padding: 1.25rem;
        border: 1px solid var(--border);
        border-radius: 18px;
        background: var(--surface);
      }

      fieldset {
        margin: 0;
        padding: 0;
        border: 0;
        min-width: 0;
      }

      legend {
        padding: 0;
        font-size: 1.125rem;
        font-weight: 700;
        line-height: 1.35;
      }

      .help-text {
        margin: 0.5rem 0 0;
        color: var(--muted);
        line-height: 1.5;
      }

      .options {
        margin-top: 1rem;
        display: grid;
        gap: 0.75rem;
      }

      .option {
        display: flex;
        align-items: flex-start;
        gap: 0.75rem;
        padding: 0.9rem 1rem;
        border: 1px solid var(--border);
        border-radius: 14px;
        background: var(--surface-alt);
        transition: border-color 0.15s ease, background 0.15s ease, transform 0.15s ease;
      }

      .option:hover {
        border-color: var(--border-strong);
        transform: translateY(-1px);
      }

      .option input {
        margin-top: 0.15rem;
        width: 1.1rem;
        height: 1.1rem;
        accent-color: var(--accent);
        flex: none;
      }

      .option span {
        line-height: 1.4;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
        padding-top: 0.25rem;
      }

      button[type="submit"] {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 0.9rem 1.35rem;
        background: linear-gradient(135deg, var(--accent), var(--accent-strong));
        color: #fff;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        box-shadow: 0 12px 24px rgba(37, 99, 235, 0.24);
      }

      button[type="submit"]:hover {
        filter: brightness(1.03);
      }

      button[type="submit"]:focus-visible,
      .option input:focus-visible,
      a.skip-link:focus-visible {
        outline: 3px solid #111827;
        outline-offset: 3px;
      }

      .status {
        margin: 0;
        min-height: 1.5em;
        color: var(--muted);
        font-size: 0.95rem;
      }

      @media (max-width: 640px) {
        main {
          width: min(100% - 1rem, 960px);
          padding-top: 4rem;
        }

        .form-field {
          padding: 1rem;
        }

        .actions {
          justify-content: stretch;
        }

        button[type="submit"] {
          width: 100%;
        }
      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --surface: Canvas;
          --surface-alt: Canvas;
          --text: CanvasText;
          --muted: CanvasText;
          --border: ButtonBorder;
          --border-strong: ButtonBorder;
          --accent: LinkText;
          --accent-strong: LinkText;
          --accent-soft: Canvas;
          --shadow: none;
        }

        .option:hover,
        button[type="submit"] {
          forced-color-adjust: auto;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content"></main>

    <script>
      const quizData = [
        {
          question: "Which of these are programming languages?",
          helpText: "Choose every option that applies.",
          options: ["Python", "HTML", "Java", "CSS"],
        },
        {
          question: "Which of these are commonly used in web development?",
          options: ["JavaScript", "TypeScript", "Go", "Ruby"],
        },
        {
          question: "Which of these are known for strong static typing?",
          options: ["Rust", "C#", "PHP", "Haskell"],
        },
      ];

      function optionItem(label, questionIndex, optionIndex) {
        const id = `q${questionIndex + 1}-option-${optionIndex + 1}`;
        return `
          <label class="option">
            <input type="checkbox" id="${id}" name="question-${questionIndex + 1}" value="${label}" />
            <span>${label}</span>
          </label>
        `;
      }

      function questionField(question, questionIndex) {
        const helpId = question.helpText ? `q${questionIndex + 1}-help` : null;
        const describedBy = helpId ? ` aria-describedby="${helpId}"` : "";
        return `
          <div class="form-field">
            <fieldset${describedBy}>
              <legend>${question.question}</legend>
              ${question.helpText ? `<p class="help-text" id="${helpId}">${question.helpText}</p>` : ""}
              <div class="options">
                ${question.options.map((option, optionIndex) => optionItem(option, questionIndex, optionIndex)).join("")}
              </div>
            </fieldset>
          </div>
        `;
      }

      function app() {
        return `
          <section class="hero" aria-labelledby="quiz-title">
            <span class="eyebrow">Product quiz</span>
            <h1 id="quiz-title">Computer languages quiz</h1>
            <p class="lead">
              Review each question and select every answer you think fits. The quiz uses standard
              form controls so it works smoothly with a keyboard or screen reader.
            </p>
          </section>

          <section class="card" aria-label="Quiz form">
            <form id="quiz-form" novalidate>
              ${quizData.map(questionField).join("")}
              <p class="status" id="quiz-status" aria-live="polite"></p>
              <div class="actions">
                <button type="submit">Submit quiz</button>
              </div>
            </form>
          </section>
        `;
      }

      document.addEventListener("DOMContentLoaded", () => {
        document.querySelector("main").innerHTML = app();

        const form = document.getElementById("quiz-form");
        const status = document.getElementById("quiz-status");

        form.addEventListener("submit", (event) => {
          event.preventDefault();

          const selections = quizData.map((question, index) => {
            const checked = Array.from(form.elements[`question-${index + 1}`] || [])
              .filter((input) => input.checked)
              .map((input) => input.value);
            return `${question.question}: ${checked.length ? checked.join(", ") : "no selections"}`;
          });

          status.textContent = `Quiz submitted. ${selections.join(" | ")}.`;
        });
      });
    </script>
  </body>
</html>
